def evaluate_buying_group_momentum(account_domain, window_days):
    # 1. Stop relying on 3rd-party IP lookups; VPNs, ZTNA, and Private Relay make reverse-DNS mostly noise
    first_party_anchors = get_deterministic_touchpoints(account_domain, window_days) # docs, signups, invites

    # 2. Buying group research has shifted to LLMs and private communities; accept we cannot track the search query
    # Instead, track downstream artifacts: sudden consumption of technical/pricing assets across distinct subnets
    consumption_spikes = detect_aggregate_read_patterns(account_domain, asset_types=["security", "pricing", "api_docs"])

    # 3. Rather than stitching pseudo-anonymous cookies to personas, model intent as multi-role arrival synchronization
    buying_group_coherence = correlate_cross_role_activity(first_party_anchors, consumption_spikes)

    # 4. If signals are sparse, reject the urge to hallucinate intent with probabilistic 3rd-party graphs
    if buying_group_coherence.entropy > NOISE_TOLERANCE:
        return IntentState(verdict="UNCERTAIN", score=0.0)

    # 5. Output a decaying momentum score tied to internal velocity rather than a static buying-stage tag
    return calculate_velocity_anomaly(buying_group_coherence)
